import { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import EmployeeService from "../Services/EmployeeService";

const ViewEmployee = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const [employee, setEmployee] = useState({});

    useEffect(() => {
        EmployeeService.getEmployeeById(id).then(res => setEmployee(res.data)).catch(err => console.log(err));
    }, []);

    return (
        <div style={{ padding: '48px 36px', background: '#e9ecef', minHeight: '100vh' }}>

            <div style={{ marginBottom: '28px' }}>
                <h3 style={{ fontWeight: '700', color: '#000', margin: 0 }}>
                    <i className="fa fa-user me-2"></i>Employee Details
                </h3>
                <p style={{ color: '#6c757d', marginTop: '4px', fontSize: '14px' }}>Viewing profile information</p>
                <hr style={{ borderColor: '#ced4da' }} />
            </div>

            <div style={{ display: 'flex', gap: '32px', alignItems: 'flex-start' }}>

                <div style={{ background: '#fff', borderRadius: '10px', padding: '36px', textAlign: 'center', width: '220px', boxShadow: '0 2px 16px rgba(0,0,0,0.08)' }}>
                    <img src="https://cdn-icons-png.flaticon.com/512/3135/3135715.png" alt="Employee"
                        style={{ width: '100px', height: '100px', borderRadius: '50%', border: '3px solid #212529', marginBottom: '16px' }} />
                    <h5 style={{ fontWeight: '700', color: '#000', marginBottom: '4px' }}>{employee.firstName} {employee.lastName}</h5>
                    <span style={{ background: '#212529', color: '#fff', borderRadius: '20px', padding: '4px 14px', fontSize: '12px' }}>Employee</span>
                </div>

                <div style={{ background: '#fff', borderRadius: '10px', padding: '36px', flex: 1, maxWidth: '560px', boxShadow: '0 2px 16px rgba(0,0,0,0.08)' }}>
                    <p style={{ fontWeight: '700', fontSize: '14px', color: '#000', marginBottom: '20px' }}>
                        <i className="fa fa-info-circle me-2"></i>Personal Information
                    </p>

                    {[
                        { label: 'First Name', value: employee.firstName, icon: 'fa-user' },
                        { label: 'Last Name', value: employee.lastName, icon: 'fa-user' },
                        { label: 'Email Address', value: employee.email, icon: 'fa-envelope' },
                    ].map((item, i) => (
                        <div key={i} style={{ display: 'flex', alignItems: 'center', padding: '14px 0', borderBottom: i < 2 ? '1px solid #e9ecef' : 'none' }}>
                            <i className={`fa ${item.icon}`} style={{ color: '#6c757d', width: '32px', fontSize: '16px' }}></i>
                            <div>
                                <div style={{ fontSize: '12px', color: '#6c757d', marginBottom: '2px' }}>{item.label}</div>
                                <div style={{ fontSize: '15px', fontWeight: '600', color: '#000' }}>{item.value}</div>
                            </div>
                        </div>
                    ))}

                    <button onClick={() => navigate('/')}
                        style={{ marginTop: '28px', background: '#212529', color: '#fff', border: 'none', padding: '12px 28px', borderRadius: '6px', fontSize: '15px', fontWeight: '600', cursor: 'pointer' }}>
                        <i className="fa fa-arrow-left me-2"></i>Back
                    </button>
                </div>

            </div>
        </div>
    );
};

export default ViewEmployee;
